<?php
declare(strict_types=1);

require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const TT_MC_ACCOUNTS = TT_DATA_DIR . '/accounts.json';
const TT_MC_OPERATIONS = TT_DATA_DIR . '/operations.json';
const TT_MC_MILLING_RATE = 3.0;

function mc_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function mc_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function mc_def():array{return ['revision'=>0,'journals'=>[],'events'=>[],'commodityBills'=>[],'localSalesCostRates'=>[],'inventoryCostRates'=>[],'managementCostingInputs'=>[],'managementCostingSheets'=>[],'managementCostingSheetHistory'=>[]];}
function mc_read_accounts():array{tt_ensure_data_dir();if(!is_file(TT_MC_ACCOUNTS))return mc_def();$h=fopen(TT_MC_ACCOUNTS,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(mc_def(),$v):mc_def();}
function mc_read_ops():array{if(!is_file(TT_MC_OPERATIONS))return ['values'=>[]];$h=fopen(TT_MC_OPERATIONS,'r');if($h===false||!flock($h,LOCK_SH))return ['values'=>[]];try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?$v:['values'=>[]];}
function mc_op(array $ops,string $key):array{$raw=$ops['values'][$key]??'';if(!is_string($raw)||$raw==='')return [];$v=json_decode($raw,true);return is_array($v)?$v:[];}
function mc_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))mc_out(['ok'=>false,'error'=>'Costing sheet is available for TTI / BRM.'],422);return $v;}
function mc_norm(string $v):string{$v=preg_replace('/[^A-Z0-9]+/i',' ',trim($v))??trim($v);return strtoupper(trim(preg_replace('/\s+/',' ',$v)??$v));}
function mc_variety(string $v):string{$u=mc_norm($v);if(str_contains($u,'IRRI 6'))$b='IRRI-6';elseif(str_contains($u,'1121'))$b='1121';elseif(str_contains($u,'PK 386'))$b='PK-386';elseif(str_contains($u,'SUPER KERNEL'))$b='SUPER KERNEL';elseif(str_contains($u,'D 98'))$b='D-98';elseif(preg_match('/(^| )C 9( |$)/',$u))$b='C-9';else$b=$u?:'RICE';if(str_contains($u,'PARBOIL')||str_contains($u,'SELLA'))$b.=' PARBOIL';return $b;}
function mc_product(string $v):string{$u=mc_norm($v);if(str_starts_with($u,'B2')||str_contains($u,'B2 SORTEX')||str_contains($u,'BROKEN B2'))return 'B2';if($u==='CSR'||str_starts_with($u,'CSR '))return 'CSR';if($u==='POWDER'||str_contains($u,' POWDER'))return 'POWDER';if($u==='PADDY'||str_contains($u,' PADDY'))return 'PADDY';if($u==='B3'||str_starts_with($u,'B3 '))return 'B3';if($u==='OTHER')return 'OTHER';return $u;}
function mc_waste(string $v):bool{$u=mc_norm($v);return str_contains($u,'STONE')||str_contains($u,'SUTLI')||str_contains($u,'DUST');}
function mc_date(string $v):string{return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)?$v:'';}
function mc_sheet_id(string $entity,string $date,string $variety):string{return 'MCS-'.substr(hash('sha256',$entity.'|'.$date.'|'.$variety),0,18);}
function mc_rate_id(string $sheet,string $product):string{return 'MCR-'.substr(hash('sha256',$sheet.'|'.mc_norm($product)),0,20);}
function mc_bill_values(array $s):array{$out=[];foreach((array)$s['commodityBills'] as $bill){if(!is_array($bill)||($bill['status']??'')!=='Verified / Posted')continue;$alloc=(array)($bill['receiptAllocations']??[]);if(!$alloc)continue;$base=0;foreach($alloc as $a)$base+=max(0,(float)($a['provisionalAmount']??0));$value=round((float)($bill['finalCommodityValue']??0)+(float)($bill['brokerageGross']??0),2);if($value<=0)continue;$used=0;$keys=array_keys($alloc);$last=end($keys);foreach($alloc as $i=>$a){$key=trim((string)($a['sourceKey']??''));if($key==='')continue;$part=$i===$last?round($value-$used,2):round($value*($base>0?max(0,(float)($a['provisionalAmount']??0))/$base:1/max(1,count($alloc))),2);$used=round($used+$part,2);$out[$key]=['value'=>$part,'billId'=>(string)($bill['id']??'')];}}return $out;}
function mc_receipts(array $s):array{$final=mc_bill_values($s);$rows=[];foreach((array)$s['events'] as $e){if(!is_array($e)||($e['eventType']??'')!=='COMMODITY_RECEIPT_ACCEPTED')continue;$j=$s['journals'][(string)($e['journalId']??'')]??null;if(!is_array($j))continue;$m=is_array($j['meta']??null)?$j['meta']:[];$kg=(float)($m['payableWeightKg']??0);if($kg<=0)continue;$src=(string)($e['sourceKey']??'');$f=$final[$src]??null;$rows[]=['entity'=>(string)($e['entity']??$j['entity']??'TTI'),'date'=>(string)($j['date']??''),'varietyKey'=>mc_variety((string)($m['variety']??'')),'kg'=>$kg,'value'=>$f?(float)$f['value']:(float)($j['totalDebit']??0),'final'=>$f!==null,'sourceKey'=>$src];}return $rows;}
function mc_production(array $ops):array{$groups=[];foreach(mc_op($ops,'tt30prod') as $p){if(!is_array($p))continue;$date=mc_date((string)($p['date']??''));if($date==='')continue;$variety=(string)($p['variety']??'Rice');$vk=mc_variety($variety);$id=$date.'|'.$vk;if(!isset($groups[$id]))$groups[$id]=['id'=>$id,'date'=>$date,'variety'=>$variety,'varietyKey'=>$vk,'inputKg'=>0.0,'readyKg'=>0.0,'outputs'=>[]];foreach((array)($p['rows']??[]) as $r){if(!is_array($r)||(!empty($r['systemFixed'])&&!empty($r['noStockPost'])))continue;$kg=(float)($r['systemKg']??0);if($kg<=0)$kg=(float)($r['bags']??0)*(float)($r['bagWeight']??0)+(float)($r['loadingAdjustmentKg']??0);if($kg<=0)continue;$name=trim((string)($r['product']??'Unknown'));$ready=str_starts_with(strtoupper($name),'READY RICE');$groups[$id]['inputKg']+=$kg;if($ready)$groups[$id]['readyKg']+=$kg;if(!isset($groups[$id]['outputs'][$name]))$groups[$id]['outputs'][$name]=['product'=>$name,'kg'=>0.0,'ready'=>$ready];$groups[$id]['outputs'][$name]['kg']+=$kg;}}foreach($groups as &$g){$g['inputKg']=round($g['inputKg'],3);$g['readyKg']=round($g['readyKg'],3);$g['outputs']=array_values($g['outputs']);foreach($g['outputs'] as &$o)$o['kg']=round((float)$o['kg'],3);unset($o);}unset($g);uasort($groups,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:strcmp((string)$a['varietyKey'],(string)$b['varietyKey']));return $groups;}
function mc_sales(array $ops):array{$rows=[];$n=0;foreach(mc_op($ops,'tt35localsales') as $x){if(!is_array($x))continue;$rate=(float)($x['rate']??0);$date=mc_date((string)($x['date']??$x['saleDate']??''));$product=trim((string)($x['product']??''));if($rate<=0||$date===''||$product==='')continue;$rows[]=['date'=>$date,'order'=>$n++,'rate'=>$rate,'product'=>$product,'key'=>mc_product($product),'reference'=>(string)($x['soda']??''),'party'=>(string)($x['party']??''),'source'=>'Mill Local Sale'];}foreach(mc_op($ops,'tt35exportersale') as $x){if(!is_array($x))continue;$rate=(float)($x['rate']??0);$date=mc_date((string)($x['date']??''));$product=trim((string)($x['product']??$x['brand']??''));if($rate<=0||$date===''||$product==='')continue;$keys=array_unique(array_filter([mc_product($product),mc_product((string)($x['brand']??''))]));foreach($keys as $key)$rows[]=['date'=>$date,'order'=>$n++,'rate'=>$rate,'product'=>$product,'key'=>$key,'reference'=>(string)($x['ref']??''),'party'=>(string)($x['buyer']??''),'source'=>'Mill Sale to Exporter'];}return $rows;}
function mc_last_sale(array $sales,string $product,string $date):?array{$key=mc_product($product);$best=null;foreach($sales as $s){if(($s['key']??'')!==$key||($s['date']??'')>$date)continue;if($best===null||$s['date']>$best['date']||($s['date']===$best['date']&&$s['order']>$best['order']))$best=$s;}return $best;}
function mc_director_input(array $s,string $entity,string $date,string $vk):?array{$best=null;foreach((array)$s['managementCostingInputs'] as $x){if(!is_array($x)||($x['entity']??'')!==$entity||($x['date']??'')!==$date)continue;$xv=mc_variety((string)($x['variety']??$x['varietyKey']??''));if($xv!==$vk)continue;$best=$x;}return $best;}
function mc_build(array $s,array $ops,string $entity):array{$groups=mc_production($ops);$receipts=array_values(array_filter(mc_receipts($s),static fn($r)=>($r['entity']??'TTI')===$entity));$sales=mc_sales($ops);$events=[];foreach($receipts as $r)$events[]=['date'=>$r['date'],'p'=>0,'kind'=>'R','data'=>$r];foreach($groups as $g)$events[]=['date'=>$g['date'],'p'=>1,'kind'=>'P','data'=>$g];usort($events,static fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:($a['p']<=>$b['p']));$pool=[];$sheets=[];foreach($events as $e){if($e['kind']==='R'){$r=$e['data'];$k=$r['varietyKey'];if(!isset($pool[$k]))$pool[$k]=['kg'=>0.0,'value'=>0.0,'provisionalKg'=>0.0];$pool[$k]['kg']+=(float)$r['kg'];$pool[$k]['value']+=(float)$r['value'];if(empty($r['final']))$pool[$k]['provisionalKg']+=(float)$r['kg'];continue;}$g=$e['data'];$k=$g['varietyKey'];$st=$pool[$k]??['kg'=>0.0,'value'=>0.0,'provisionalKg'=>0.0];$avg=$st['kg']>0?$st['value']/$st['kg']:0;$need=(float)$g['inputKg'];$enough=$st['kg']+.001>=$need;$consume=min($need,(float)$st['kg']);$provisional=$st['kg']>0?(float)$st['provisionalKg']*($consume/$st['kg']):0;if($consume>0){$st['kg']-=$consume;$st['value']-=$consume*$avg;$st['provisionalKg']=max(0,$st['provisionalKg']-$provisional);$pool[$k]=$st;}$input=mc_director_input($s,$entity,$g['date'],$k);$rawRate=(float)($input['rawRiceRate']??0);$rawSource=$rawRate>0?'Directors Daily Costing':'Purchase Cost';if($rawRate<=0)$rawRate=$avg;$millRate=(float)($input['millingRate']??0);$millSource=$millRate>0?'Directors Daily Costing':'Fallback Rs 3/kg';if($millRate<=0)$millRate=TT_MC_MILLING_RATE;$rawValue=round($need*$rawRate,2);$millingValue=round($need*$millRate,2);$by=[];$byValue=0.0;$missing=[];foreach($g['outputs'] as $o){if(!empty($o['ready']))continue;$name=(string)$o['product'];$kg=(float)$o['kg'];if(mc_waste($name)){$by[]=['product'=>$name,'kg'=>$kg,'rate'=>0,'value'=>0,'rateSource'=>'Waste / Nil','saleDate'=>'','saleReference'=>''];continue;}$pk=mc_product($name);$directorRates=(array)($input['byProducts']??[]);$rate=isset($directorRates[$pk])?(float)$directorRates[$pk]:(isset($directorRates[$name])?(float)$directorRates[$name]:0);$src='';$saleDate='';$saleRef='';$party='';if($rate>0)$src='Directors Daily Costing';else{$sale=mc_last_sale($sales,$name,$g['date']);if($sale){$rate=(float)$sale['rate'];$src='Last Mill Sale';$saleDate=(string)$sale['date'];$saleRef=(string)$sale['reference'];$party=(string)$sale['party'];}}if($rate<=0){$missing[]=$pk;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>null,'value'=>null,'rateSource'=>'No previous Mill sale','saleDate'=>'','saleReference'=>''];continue;}$value=round($kg*$rate,2);$byValue+=$value;$by[]=['product'=>$name,'kg'=>$kg,'rate'=>$rate,'value'=>$value,'rateSource'=>$src,'saleDate'=>$saleDate,'saleReference'=>$saleRef,'party'=>$party];}$readyValue=round($rawValue+$millingValue-$byValue,2);$readyRate=$g['readyKg']>0&&$readyValue>0?$readyValue/$g['readyKg']:0;$status='Ready';if(!$enough)$status='Waiting — raw rice stock is short';elseif($rawRate<=0)$status='Waiting — raw rice cost is missing';elseif($g['readyKg']<=0)$status='Waiting — Ready Rice output is missing';elseif($missing)$status='Waiting — no previous Mill sale for '.implode(', ',$missing);elseif($readyValue<=0)$status='Waiting — by-product value is too high';$sid=mc_sheet_id($entity,$g['date'],$k);$sheets[$sid]=['id'=>$sid,'entity'=>$entity,'date'=>$g['date'],'variety'=>$g['variety'],'varietyKey'=>$k,'inputKg'=>$need,'readyRiceKg'=>$g['readyKg'],'rawRiceRate'=>round($rawRate,6),'rawRiceRateSource'=>$rawSource,'rawRiceValue'=>$rawValue,'usesProvisionalPurchaseCost'=>$provisional>.001,'millingRatePerKg'=>round($millRate,6),'millingRateSource'=>$millSource,'millingValue'=>$millingValue,'byProducts'=>$by,'byProductValue'=>round($byValue,2),'estimatedReadyRiceValue'=>$readyValue,'estimatedReadyRiceCostPerKg'=>round($readyRate,6),'missingByProductRates'=>array_values(array_unique($missing)),'status'=>$status,'ready'=>$status==='Ready','sourceMode'=>$input?'Directors / Fallback':'Fallback','builtAt'=>gmdate('c'),'note'=>'Live management costing sheet. Final Accounts stock cost may later replace this estimate.'];}return array_values($sheets);}
function mc_sync_rates(array &$s,array $sheets):void{$active=[];$genericDates=[];foreach($sheets as $sh)if(!empty($sh['ready']))$genericDates[$sh['date']][]= $sh;foreach($sheets as $sh){if(empty($sh['ready']))continue;$aliases=[];$readyProducts=[];$prod=mc_production(mc_read_ops());foreach($prod as $g)if($g['date']===$sh['date']&&$g['varietyKey']===$sh['varietyKey'])foreach($g['outputs'] as $o)if(!empty($o['ready']))$readyProducts[]=(string)$o['product'];$aliases=array_values(array_unique(array_merge($readyProducts,[(string)$sh['variety']])));if(count($genericDates[$sh['date']]??[])===1)$aliases[]='Ready Rice';$rid=mc_rate_id($sh['id'],(string)$sh['variety']);$active[$rid]=true;$s['localSalesCostRates'][$rid]=['id'=>$rid,'entity'=>$sh['entity'],'product'=>$sh['variety'],'aliases'=>array_values(array_unique($aliases)),'effectiveFrom'=>$sh['date'],'costPerKg'=>$sh['estimatedReadyRiceCostPerKg'],'inventoryAccount'=>'1320','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'notes'=>'Live estimate from costing sheet; final approved stock cost overrides this estimate.','updatedAt'=>gmdate('c')];foreach($sh['byProducts'] as $bp){if($bp['rate']===null||mc_waste((string)$bp['product']))continue;$bid=mc_rate_id($sh['id'],(string)$bp['product']);$active[$bid]=true;$s['localSalesCostRates'][$bid]=['id'=>$bid,'entity'=>$sh['entity'],'product'=>$bp['product'],'aliases'=>[mc_product((string)$bp['product'])],'effectiveFrom'=>$sh['date'],'costPerKg'=>$bp['rate'],'inventoryAccount'=>'1330','status'=>'Active','source'=>'MANAGEMENT_COSTING_SHEET','costingSheetId'=>$sh['id'],'estimateOnly'=>true,'notes'=>'By-product management value from Directors rate or latest Mill sale.','updatedAt'=>gmdate('c')];}}foreach($s['localSalesCostRates'] as $id=>&$r)if(is_array($r)&&($r['source']??'')==='MANAGEMENT_COSTING_SHEET'&&!isset($active[$id]))$r['status']='Superseded';unset($r);}
function mc_payload(array $s,array $ops,string $entity):array{$sheets=mc_build($s,$ops,$entity);usort($sheets,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date'])?:strcmp((string)$a['variety'],(string)$b['variety']));return ['ok'=>true,'entity'=>$entity,'sheets'=>$sheets,'millingFallbackRate'=>TT_MC_MILLING_RATE,'serverNow'=>gmdate('c')];}

try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))mc_out(['ok'=>false,'error'=>'Accounts permission required.'],403);$entity=mc_entity((string)($_GET['entity']??'TTI'));if($_SERVER['REQUEST_METHOD']==='GET')mc_out(mc_payload(mc_read_accounts(),mc_read_ops(),$entity));if($_SERVER['REQUEST_METHOD']!=='POST')mc_out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!mc_can_write($u))mc_out(['ok'=>false,'error'=>'Accounts Create, Edit or Approve permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))mc_out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if(($b['action']??'')!=='refresh_sheets')mc_out(['ok'=>false,'error'=>'Unknown costing-sheet action.'],422);$entity=mc_entity((string)($b['entity']??$entity));tt_ensure_data_dir();$h=fopen(TT_MC_ACCOUNTS,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');try{rewind($h);$raw=stream_get_contents($h);$s=$raw?json_decode($raw,true):null;if(!is_array($s))$s=mc_def();$s=array_replace_recursive(mc_def(),$s);$ops=mc_read_ops();$sheets=mc_build($s,$ops,$entity);foreach($sheets as $sh){$old=$s['managementCostingSheets'][$sh['id']]??null;if(is_array($old)&&json_encode($old)!==json_encode($sh)){$hid=$sh['id'].'|'.gmdate('YmdHis');$s['managementCostingSheetHistory'][$hid]=$old;}$s['managementCostingSheets'][$sh['id']]=$sh;}mc_sync_rates($s,$sheets);$s['revision']=(int)($s['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($s,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);}finally{flock($h,LOCK_UN);fclose($h);}mc_out(mc_payload($s,$ops,$entity)+['revision'=>$s['revision']]);}catch(Throwable $e){mc_out(['ok'=>false,'error'=>'Costing sheet could not be prepared.'],500);}
